        for label, supplied in [("equal", SECRET), ("first", "X" + SECRET[1:]), ("middle", SECRET[:9] + "X" + SECRET[10:]), ("last", SECRET[:-1] + "X")]:
            result, log = trace(m.verify_token, supplied, SECRET)
            self.assertEqual(result, label == "equal")
            logs[label] = log
