        self.assertIs(m.safe_equals("", ""), True)
        self.assertIs(m.safe_equals("éa", "éa"), True)
        for a, b in [("abc", "abd"), ("abc", "ab"), ("", "a"), ("é", "e"), ("abc", "ABC")]:
            self.assertIs(m.safe_equals(a, b), False, (a, b))

